DROP TABLE IF EXISTS `hub_items`;
CREATE TABLE `hub_items` (
  `id` VARCHAR(50) NOT NULL,
  `category` VARCHAR(50) NOT NULL,
  `title` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `date` VARCHAR(50) NOT NULL,
  `coverImage` TEXT NOT NULL,
  `deadline` VARCHAR(50) NULL,
  `location` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `salaryRange` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `requirements` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `order` INT NOT NULL DEFAULT 0,
  `additionalImages` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `trainingButtonText` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `trainingButtonLink` VARCHAR(255) NULL,
  `customUrl` VARCHAR(255) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `hub_items` (`id`, `category`, `title`, `summary`, `content`, `date`, `coverImage`, `deadline`, `location`, `salaryRange`, `requirements`, `order`, `additionalImages`, `trainingButtonText`, `trainingButtonLink`, `customUrl`) VALUES ('h1780482227821', 'news', 'ქალაქ ფოთის მუნიციპალიტეტის, ახალგაზრდული ჰაბის გახსნა ', 'ადგილი, სადაც მემკვიდრეობა ხვდება ახალ შესაძლებლობებს / Where heritage meets new opportunity', 'საქართველოს პრემიერ-მინისტრთან ირაკლი კობახიძესთან, მთავრობისა და პარლამენტის წევრებთან ერთად, ჩვენს ქალაქში ახალგაზრდული ინოვაციური ჰაბი გავხსენით.\nგანსაკუთრებით საამაყოა, რომ ჰაბი განთავსდა ნაგებობაში, რომელიც ნიკო ნიკოლაძის მოღვაწეობის პერიოდშია აგებული და კულტურული მემკვიდრეობის ძეგლს წარმოადგენს. შესრულებული სამუშაოებით შენობას სრულად შეუნარჩუნდა ისტორიული ავთენტურობა.\nმრავალფუნქციურ სივრცეში ჩვენი ახალგაზრდები შეძლებენ ცოდნის გაღრმავებას, ინოვაციური და მეწარმეობრივი უნარების განვითარებას, ახალი იდეების განხორციელებასა და საინტერესო აქტივობებში მონაწილეობას. დარწმუნებული ვარ, ჰაბი იქცევა ადგილად, რომელიც ჩვენს ახალგაზრდებს უამრავ ახალ შესაძლებლობას გაუხსნის.\n', '2025-09-18 12:00', 'data:image/webp;base64,', NULL, NULL, NULL, '[]', 0, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', NULL, NULL, NULL);
INSERT INTO `hub_items` (`id`, `category`, `title`, `summary`, `content`, `date`, `coverImage`, `deadline`, `location`, `salaryRange`, `requirements`, `order`, `additionalImages`, `trainingButtonText`, `trainingButtonLink`, `customUrl`) VALUES ('h1780482738564', 'news', 'მემორანდუმი / Memorandum', 'მემორანდუმის გაფორმება ,,სტივ პოლ ჯობსის  ამერიკულ აკადემიასთან" / Signing of a Memorandum of Understanding with the Steve Paul Jobs American Academy ', 'ახალგაზრდულ ჰაბში, „სტივ პოლ ჯობსის ამერიკულ აკადემიასთან“ ურთიერთთანამშრომლობის მემორანდუმს მოვაწერეთ ხელი.\nეს თანამშრომლობა ჩვენს ახალგაზრდებს მისცემს შესაძლებლობას, განივითარონ ტექნოლოგიური უნარები, ინოვაციური აზროვნება და კიდევ უფრო გააძლიერონ საკუთარი ადგილი თანამედროვე სამყაროში.\nდარწმუნებული ვარ, ახალგაზრდული ჰაბი გახდება სივრცე, სადაც დაიბადება ინოვაციური პროექტები და ახალი იდეები ჩვენი ქალაქის განვითარებისათვის.\nთანამშრომლობის ფარგლებში დაარსდა ახალგაზრდული სტიპენდია - „შესაძლებლობები საზღვრების გარეშე“, რომლის პირველი სტიპენდიანტი გახდა ქეთევან სურმავა. \nვულოცავ მას და დარწმუნებული ვარ, მომავალში მნიშვნელოვან წვლილს შეიტანს ჩვენი ქალაქის განვითარებაში.\nგანსაკუთრებული მადლობა ჩვენს პარტნიორსა და მხარდამჭერს, „ეი პი ემ ტერმინალს ფოთს“ და ორგანიაცია IOCC-ს. \nკერძო-საჯარო თანამშრომლობის ფარგლებში, გავაგრძელებთ ახალი შესაძლებლობების შექმნას ჩვენი ქალაქისათვის.\n', '2025-09-20 12:00', 'data:image/webp;base64,', NULL, NULL, NULL, '[]', 0, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', NULL, NULL, NULL);
INSERT INTO `hub_items` (`id`, `category`, `title`, `summary`, `content`, `date`, `coverImage`, `deadline`, `location`, `salaryRange`, `requirements`, `order`, `additionalImages`, `trainingButtonText`, `trainingButtonLink`, `customUrl`) VALUES ('h1780483947829', 'news', 'წიგნის საჯაროდ კითხვის მსოფლიო დღე / World Public Reading Day', 'ახალგაზრდულ ჰაბში, პატარებთან ერთად მსოფლიო წიგნის კითხვის დღე / World Book Day with the kids at the Youth Hub', 'ახალგაზრდულ ჰაბში, ქალაქ ფოთის მუნიციპალიტეტის მერთან, ბატონ ბექა ვაჭარაძესთან ერთად წიგნის საჯაროდ კითხვის მსოფლიო დღე აღინიშნა.\n\n', '2026-02-09 12:00', 'data:image/webp;base64,', NULL, NULL, NULL, '[]', 0, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,